ATTR_WIDTHS: Mapping[int, int] = {
    ATTR_IDS[n]: w for n, w in _WIDTHS_BY_NAME.items() if n in ATTR_IDS
}


def attr_id(name: str) -> int | None:
    """The global id for ``name``, or ``None`` if the vendor publishes none."""
    return ATTR_IDS.get(name)


def attr_name(ident: int) -> str | None:
    """The attribute a global id addresses, or ``None``."""
    return ATTR_NAMES.get(ident)
